) AS (
  VALUES 
    (550::BIGINT, 'las clases están grabadas, explica muy bien y se devuelve las veces que sea necesario. Trata de hacer la clase entretenida. Da repasos virtuales antes de los examenes, es una teja de persona. Tqm profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2026-09-16T00:00:00+00:00'::TIMESTAMPTZ, '8d6905150d5b91340ecc7387a23c0e15ab7c0756a3fea8137c6d0e87477e2ffd'::TEXT, ARRAY[568]::BIGINT[]),
    (550::BIGINT, 'Se pasa super facil con el, ya que todas las clases las tiene grabadas, da quizzes extras de ayuda, califica suave, y es muy buena persona. Eso si, hay que participar en clase. Da repaso para los examenes. Lo recomiendo mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-07-15T00:00:00+00:00'::TIMESTAMPTZ, '26fe57cc2d7ca57e1f9f990a9c0581e3c8789f613c2546909a26366a9d788833'::TEXT, ARRAY[568]::BIGINT[]),
    (550::BIGINT, 'Uno de los mejores profes que he tenido en la vida. Es increíblemente razonable, acepta apelaciones y si ud tiene razón le da los puntos defijo. Hace las clases bien entretenidas y explica demasiado bien. Matricule con él sin pensarlo dos veces porq se está haciendo un favor a ud mismo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'dfc0123a5085ea393e0793848b7c22c8a270e5edda37a01155e4d0812213831e'::TEXT, ARRAY[568]::BIGINT[]),
    (550::BIGINT, 'Me encantó el curso. El profe es excelente, explica súper bien y no es nada excesivo con quizzes o trabajos. Muy buen profe si quieres aprender, pero tampoco estar ahogado en trabajos como otros profes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-27T00:00:00+00:00'::TIMESTAMPTZ, '1a00f45f2c630ce7b3b1196b322fd5af0dd66b76001995f30c52c3b132e410af'::TEXT, ARRAY[568]::BIGINT[]),
    (550::BIGINT, 'Excelente profesor de quimica, se nota que sabe enseñar y si usd no entiende algo se esfuerza en explicarle hasta que entienda. Es bastante dinamico y sabe cono hacer que los estudiantec participen en su clase.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchos exámenes', 'Clases excelentes']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'b9640277c47c027eb8d8d056bac2a1c8c8c83039559f502b6edf86d4d81beb3c'::TEXT, ARRAY[568]::BIGINT[]),
    (550::BIGINT, 'Excelente profesor, facilidad para explicar, se preocupa por el rendimiento individual de cada estudiante, siempre dispuesto a ayudar y explicar. Hace que todos participen en clase de manera divertida lo que facilita la comprensión de los temas. Se caracteriza por su alegría y es una calidad de pers'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, '85b63138bf9c83c61da24adcbd538aa0ea421880419a6f45a0fda275d78d74ce'::TEXT, ARRAY[568, 614]::BIGINT[]),
    (550::BIGINT, 'El mejor profesor que he tenido en lo que llevo de U, ayuda mucho en caso de no entender'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-10-04T00:00:00+00:00'::TIMESTAMPTZ, '412861fe51147722a023a10276c6db70715e31745d6d0c24cd44747c54602483'::TEXT, ARRAY[568, 614]::BIGINT[]),
    (550::BIGINT, 'El prof Ricardo es el mejor profe con el que he topado. Preocupado porque todos entiendan, las clases son muy amigables que uno se sienta comodo, hace quiz extra para ayudarlo a uno.Una persona humilde y comico sin duda lo recomendaria 1000 veces en quimica 1 me regalo un punto para pasar la repo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2023-10-30T00:00:00+00:00'::TIMESTAMPTZ, '9d0ec5b8b96129d1a8396bfe038599ea45aa451ba223ce6e00f5151687de48cc'::TEXT, ARRAY[567, 613, 568, 614]::BIGINT[]),
    (550::BIGINT, 'Una maravilla de profesor, llevé dos cursos con él y es el mejor, no dude en matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a823b036f3cf99619620cc6198cfacd3491e2db77829ed846fdd3b9c3010ae69'::TEXT, ARRAY[567, 613, 568, 614]::BIGINT[]),
    (550::BIGINT, 'El mejor profesor , un ser humano increíble, compresivo con los estudiantes, explica muy bien su materia, evalua justo, se preocupa porque sus estudiantes aprendan. Siempre lo van a encontrar en las horas consulta y explica aún mejor y más detallado que en clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, '0905654a675a720c200455ff7f0388b61aa1d2d107cbfda939ae4025d146c71a'::TEXT, ARRAY[567, 613]::BIGINT[]),
    (550::BIGINT, 'No por nada en el 2020 fue valorado como uno de los mejores profes de la escuela de química.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-12-10T00:00:00+00:00'::TIMESTAMPTZ, '6fb9f631abc97e054300876e5793f571debe0a2d22c1469368c2fea444db2d8f'::TEXT, ARRAY[568]::BIGINT[]),
    (550::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '05b72b999cca2cf58b1b8dabf5c8a03fead6d95f72ccb974b5a02b3f834617e4'::TEXT, ARRAY[568]::BIGINT[]),
    (550::BIGINT, 'Explica las veces que sea necesario, busca la manera de que entienda, no aburrido, enseña muy bien, da mucha ayuda, examenes no tan duros y da quices extra que te eliminan los quices malos, el mejor profe de quimica que he tenido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'ae69915222f173494bf809afe1e219e8decfc0633372963b5ebfbb9e363d6cd1'::TEXT, ARRAY[568]::BIGINT[]),
