    (550::BIGINT, 'Excelente profesor, se toma el tiempo para explicarle las veces que sean necesariaa, si usted no entiende de una forma, busca la manera de que entienda, clases interactivas, enseña muy bien, da mucha ayuda, no dude en llevar con él, de verdad es de los mejores profes que tiene el TEC'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-04-12T00:00:00+00:00'::TIMESTAMPTZ, 'ea330add0f9a57bb242850c3ef97809e93a678166c1cbc6f2aa208893cd519ab'::TEXT, ARRAY[614, 568]::BIGINT[]),
