    (550::BIGINT, 'Uno de los mejores profesores de química. Sus clases son interesantes y se entienden con claridad. Si usted tiene una duda,el la aclara las veces que sean necesarias. Tomaría otro curso con él si fuera posible!!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-24T00:00:00+00:00'::TIMESTAMPTZ, '27e7a76f0d988d26ce80b152be23e269803d35d34295ec5d5ae118b51b2168b6'::TEXT, ARRAY[567, 613]::BIGINT[]),
    (550::BIGINT, 'Lo mejor del TEC de Limón, hace clases fuera de horario para repasar más, siempre dispuesto a ayudar. No dude matricular con él. Además deja examenes viejos que cambia por 100 en el quiz más bajo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2020-02-07T00:00:00+00:00'::TIMESTAMPTZ, '8c168b8965cabeb645bc7b70ceab9372516db6fd3e90963cbfe129a355f278d0'::TEXT, ARRAY[567, 613, 568, 614]::BIGINT[]),
    (550::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2019-06-05T00:00:00+00:00'::TIMESTAMPTZ, '8861527232d454293b6cee54660a610db7d08e2faef4d73dcde1492f0c9a22e6'::TEXT, ARRAY[568]::BIGINT[]),
